1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	
3	// A task decides whether it runs in its PRECONDITION, and nowhere else (owner,
4	// 2026-08-06). Once the precondition says run, the two execution phases —
5	// deterministic prework, then agentic work — do the work; neither may discover
6	// a new reason to skip it for state, timing, or "already handled" reasons.
7	// Failures are allowed to stop a run; discretion is not. "The work ran and
8	// produced nothing" is always legal — that is an outcome, not a skip.
9	//
10	// This is the check-the-world sweep that hunts for tasks that ESCAPE in the
11	// later phases: instruction files (task.md) telling the agent to stop or skip
12	// when some state holds, and prework workers logging that they are skipping a
13	// cycle. It is a HEURISTIC over natural language, so it is advisory — its job
14	// is to surface candidates for a human (or the authoring session) to judge, and
15	// the tell-tale phrases were taken from real violations found in the 2026-08-06
16	// audit, not invented.
17	//
18	// Exemption: a line that scopes by the dispatch issue's `Context` is the
19	// precondition speaking (its verdict lands there verbatim), so "skip this half
20	// when Context says it is out of scope" is precondition-decided, not an escape.
21	// RELEVANCE FIRST: keyed on tasks/<name>/ files, inert on a repo without tasks.
22	const TASK_MD = /(^|\/)tasks\/[^/]+\/task\.md$/;
23	const TASK_HELPER_MJS = /(^|\/)tasks\/[^/]+\/[^/]+\.mjs$/;
24	const TASK_DECL = /(^|\/)task\.mjs$/;
25	
26	// A skip word next to a condition word, in one instruction line. `stop` is
27	// matched lowercase-only on purpose: capitalized "Stop" in this corpus is the
28	// harness's Stop hook, not an instruction to stop.
29	const SKIP_WORD = /\b([Ss]kip(?:s|ped|ping)?|stop(?: here)?|[Aa]bort|[Bb]ail(?: out)?|[Dd]o\s+(?:\*\*?not\*\*?|not)\s+(?:run|proceed|continue|stack)|[Ll]eav(?:e|ing)\s+(?:it\s+|this\s+)?(?:cycle'?s?\s+)?(?:converge\s+)?undelivered)\b/;
30	const CONDITION_WORD = /\b(if\b|when\b|unless\b|already\b|still\s+(?:open|running|unreviewed)|(?:nothing|no\s+new|not?\s+\w+)\s+(?:changed|has\s+changed)|before\s+(?:anything|starting|researching)|unset\s+means|absent\b)\b/i;
31	// Two legal shapes share the vocabulary: a scope carved by the precondition's
32	// Context, and a line DESCRIBING the precondition's own verdicts (status
33	// vocabulary like "skipped (its precondition said no)").
34	const CONTEXT_EXEMPT = /\bContext\b|\bprecondition\b/;
35	
36	// A prework worker announcing it decided not to do this cycle's work.
37	const WORKER_SKIP_STRING = /(skip(?:ping)?\s+this\s+(?:cycle|run)|leaving\s+this\s+cycle|cycle\s+skips|nothing\s+to\s+self-refresh)/i;
38	
39	const rule = {
40	  id: 'task-phase-discipline',
41	  severity: 'advisory',
42	  description: 'After a task\'s precondition passes, neither phase of its execution (prework, agentic work) decides to skip the run for state/timing reasons — flags skip-language in task.md instructions and cycle-skip strings in prework workers',
43	  doc: 'packs/basics/scheduled-tasks.md',
44	  why: 'the precondition is the ONLY decision point: a later-phase skip hides work from the run records (a "ran, did nothing" that was really "declined to run"), re-litigates a verdict already given, and belongs in the precondition where it is code over signals',
45	
46	  run(ctx) {
47	    const out = [];
48	    for (const file of ctx.files.filter((f) => TASK_MD.test(f))) {
49	      const text = ctx.read(file);
50	      if (text === null) continue;
51	      text.split('\n').forEach((line, i) => {
52	        if (!SKIP_WORD.test(line) || !CONDITION_WORD.test(line)) return;
53	        if (CONTEXT_EXEMPT.test(line)) return; // precondition-derived scope, not an escape
54	        out.push(finding(rule, {
55	          file,
56	          line: i + 1,
57	          what: `instructs a conditional skip after the precondition already passed: "${line.trim().slice(0, 120)}"`,
58	          fix: 'move the run/no-run decision into the task.mjs precondition (as code over signals, its verdict binding via Context) — or, if the work genuinely ran and found nothing, reword so it reads as an empty outcome, not a decision to skip',
59	        }));
60	      });
61	    }
62	    for (const file of ctx.files.filter((f) => TASK_HELPER_MJS.test(f) && !TASK_DECL.test(f))) {
63	      const text = ctx.read(file);
64	      if (text === null) continue;
65	      text.split('\n').forEach((line, i) => {
66	        const m = WORKER_SKIP_STRING.exec(line);
67	        if (!m) return;
68	        out.push(finding(rule, {
69	          file,
70	          line: i + 1,
71	          what: `prework announces a discretionary cycle skip ("${m[1]}") — work its precondition asked for was declined in a later phase`,
72	          fix: 'let the precondition make that call, or complete the work and report an empty outcome; only a genuine failure may stop a run past the precondition',
73	        }));
74	      });
75	    }
76	    return out;
77	  },
78	};
79	
80	export default rule;
