3	// A member must have SOMETHING in CI that runs the world sweep on every pull
4	// request — otherwise its own conformance is never gated, and (worse) its
5	// nightly maintenance PR can never land.
6	//
7	// WHY THIS IS ITS OWN RULE. `maintenance.delivery: auto-merge` arms GitHub's
8	// auto-merge, which is a queue for CHECKS. Three shapes exist, and only one
9	// works:
10	//
11	//   no pull_request workflow at all  → baselining merges directly (#588). Fine.
12	//   an UNFILTERED conformance flow   → the sweep runs, auto-merge lands on green.
13	//   a PATH-FILTERED flow             → the arm succeeds, and no check ever runs.
14	//                                      The PR waits forever. THIS is the trap.
15	//
16	// The third shape is invisible: the repo looks like it has CI, `hasPrCi` is
17	// true, the arm reports success, and the PR simply never lands. TLDR sat in it —
18	// all three of its test workflows filter to `extension/**`, `server/**`,
19	// `dev/requirements/**`, so a maintenance PR touching only `.claudinite/**`
20	// matched nothing. The same filters also hid two blocking `claudinite-isolation`
21	// findings on its `main` for as long as they had existed.
22	//
23	// ADVISORY, DELIBERATELY. Shipping this blocking would turn every member that
24	// lacks the workflow red on its very next baselining — which is precisely the
25	// #555 failure this rule exists to make less likely (a required thing added to
26	// the canon with no path for consumers to comply first). It becomes blocking
27	// once the fleet carries the workflow; the promotion is a one-line change here.
28	//
29	// RELEVANCE FIRST (engine/checks/README.md): gate on the vendored mount, so this
30	// is inert in any repo that is not a Claudinite member.
31	const SWEEP = 'engine/checks/check_the_world.mjs';
32	const MOUNT = '.claudinite/shared/engine/checks/check_the_world.mjs';
33	const WORKFLOW_DIR = '.github/workflows/';
34	
35	// The `on:` block alone — from the `on:` key to the next top-level key. Trigger
36	// filters (`paths:`) are nested INSIDE it, so scanning the whole file would
37	// confuse a job-level key with a trigger-level one.
38	export function onBlock(text) {
39	  const start = text.search(/^on:/m);
40	  if (start < 0) return '';
41	  const rest = text.slice(start).split('\n');
42	  const out = [rest[0]];
43	  for (const line of rest.slice(1)) {
44	    if (/^[A-Za-z_-]+:/.test(line)) break; // next top-level key
45	    out.push(line);
46	  }
47	  return out.join('\n');
48	}
49	
50	// Does this workflow run the world sweep on EVERY pull request? Both halves
51	// matter: a sweep behind a path filter is not a gate, it is a gate that happens
52	// to be open.
53	export function gatesEveryPull(text) {
54	  const on = onBlock(text);
55	  if (!/^\s+pull_request:/m.test(on)) return { pull: false, filtered: false, sweeps: false };
56	  // The pull_request sub-block: its own indented lines, up to the next trigger.
57	  const lines = on.split('\n');
58	  const at = lines.findIndex((l) => /^\s+pull_request:/.test(l));
59	  const indent = lines[at].search(/\S/);
60	  const body = [];
61	  for (const line of lines.slice(at + 1)) {
62	    if (line.trim() && line.search(/\S/) <= indent) break;
63	    body.push(line);
64	  }
65	  return {
66	    pull: true,
67	    filtered: /^\s*paths(-ignore)?:/m.test(body.join('\n')),
68	    sweeps: text.includes(SWEEP),
69	  };
70	}
71	
72	const rule = {
73	  id: 'conformance-workflow',
74	  severity: 'advisory',
75	  description: 'A member has a workflow running check_the_world on every pull request, with no path filter',
76	  doc: 'packs/basics/scheduled-tasks.md',
77	  why: 'auto-merge is a queue for checks — a path-filtered conformance flow arms successfully and then never runs, so the nightly maintenance PR waits forever and the repo silently stops baselining',
78	
79	  run(ctx) {
80	    if (!ctx.files.includes(MOUNT)) return [];  // not a member — inert
81	    const workflows = ctx.files.filter((f) => f.startsWith(WORKFLOW_DIR) && /\.ya?ml$/.test(f));
82	
83	    const filtered = [];
84	    for (const file of workflows) {
85	      const text = ctx.read(file);
86	      if (text === null) continue;
87	      const { pull, filtered: hasFilter, sweeps } = gatesEveryPull(text);
88	      if (!pull || !sweeps) continue;
89	      if (!hasFilter) return [];              // a real gate exists — done
90	      filtered.push(file);
91	    }
92	
93	    // A repo with NO pull_request workflow at all is not flagged: baselining
94	    // merges its maintenance PR directly (#588), which is a coherent shape. The
95	    // finding is for the trap — a sweep that exists but cannot run.
96	    if (!filtered.length && !workflows.some((f) => /^\s+pull_request:/m.test(ctx.read(f) ?? ''))) return [];
97	
98	    return [finding(rule, {
99	      file: filtered[0] ?? WORKFLOW_DIR,
100	      what: filtered.length
101	        ? `${filtered[0]} runs the world sweep on pull_request but behind a path filter, so a maintenance PR touching only .claudinite/** starts no check`
102	        : 'this repo has pull_request workflows but none of them runs the world sweep, so its conformance is never gated on a PR',
103	      fix: 'add a conformance workflow triggered on `pull_request` with NO `paths:` filter (plus `workflow_dispatch:` so baselining can start it) running '
104	        + '`node .claudinite/shared/engine/checks/check_the_world.mjs` — or drop the path filter from the workflow that already runs it',
105	    })];
106	  },
107	};
108	
109	export default rule;
